struct alignas(64) CacheOptimizedCounter {
    // Ensuring the counter occupies its own cache line (e.g., 64 bytes)
    // Avoids 'False Sharing' in multi-threaded environments,
    // where updates by one CPU invalidate a shared cache line on another CPU.
    volatile long count;

    // Optional explicit padding (less modern, alignas preferred):
    // char padding[64 - sizeof(long)]; 
};

CacheOptimizedCounter thread_metrics[8]; // Array of counters

void increment(int thread_id) {
    thread_metrics[thread_id].count++;
}
